334: function drawAnimal(animal, time) {
335:   const { width, height, scale } = dimensions;
336:   const position = animalPosition(animal, width, height, scale);
337:   const x = (position.x - position.offsetX) / scale;
338:   const y = (position.y - position.offsetY) / scale;
339:   const bob = Math.sin(time * .002 + animal.mood * 2 + x) * 3;
340:   const size = animal.size;
341:   ctx.save(); ctx.translate(x, y + bob);
342:   ctx.fillStyle = '#57794b35'; ctx.beginPath(); ctx.ellipse(0, size * .5, size * .66, size * .18, 0, 0, Math.PI * 2); ctx.fill();
343:   // Soft illustrated character medallion behind each friend.
344:   ctx.fillStyle = animal.color; ctx.beginPath(); ctx.arc(0, 0, size * .56, 0, Math.PI * 2); ctx.fill();
345:   ctx.strokeStyle = '#fff8df'; ctx.lineWidth = 4; ctx.beginPath(); ctx.arc(0, 0, size * .56 - 2, 0, Math.PI * 2); ctx.stroke();
346:   ctx.font = `${size * .82}px "Apple Color Emoji","Segoe UI Emoji",sans-serif`;
347:   ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
348:   ctx.fillText(animal.emoji, 0, 4);
349:   // Name plaque.
350:   const plaqueW = animal.name.length * 9 + 24;
351:   ctx.fillStyle = '#fffdf1'; roundedRect(ctx, -plaqueW / 2, size * .48, plaqueW, 24, 12); ctx.fill();
352:   ctx.fillStyle = '#476b4e'; ctx.font = '700 12px "DM Sans",sans-serif'; ctx.textBaseline = 'middle'; ctx.fillText(animal.name, 0, size * .48 + 12);
353:   // Favorite snack bubble floats over each animal.
354:   const bubbleY = -size * .63 + Math.sin(time * .0018 + x) * 2;
355:   ctx.fillStyle = '#fffdf5'; ctx.beginPath(); ctx.arc(size * .45, bubbleY, 20, 0, Math.PI * 2); ctx.fill();
356:   ctx.strokeStyle = '#f6edce'; ctx.lineWidth = 2; ctx.stroke();
357:   ctx.font = '20px "Apple Color Emoji","Segoe UI Emoji",sans-serif'; ctx.fillText(foodById(animal.food).emoji, size * .45, bubbleY + 1);
358:   if (animal.happy) {
359:     ctx.fillStyle = '#f6bd63'; ctx.font = '700 17px sans-serif'; ctx.fillText('♥', -size * .42, -size * .55 + Math.sin(time * .004) * 3);
360:   }
361:   ctx.restore();
362: }
