379: function drawAim() {
380:   if (!isAiming || !aim || projectile) return;
381:   const target = nearestAnimal(aim);
382:   ctx.save();
383:   ctx.strokeStyle = target ? '#fff9dfc9' : '#fff9df99';
384:   ctx.lineWidth = 2;
385:   ctx.setLineDash([6, 8]);
386:   ctx.beginPath();
387:   ctx.moveTo(dimensions.width * .74, dimensions.height * .9);
388:   ctx.quadraticCurveTo((dimensions.width * .74 + aim.x) / 2, aim.y - 65, aim.x, aim.y);
389:   ctx.stroke();
390:   ctx.setLineDash([]);
391:   ctx.beginPath(); ctx.arc(aim.x, aim.y, target ? 25 : 17, 0, Math.PI * 2); ctx.stroke();
392:   ctx.fillStyle = target ? '#fff9df' : '#fff9dfbb';
393:   ctx.beginPath(); ctx.arc(aim.x, aim.y, 3, 0, Math.PI * 2); ctx.fill();
394:   ctx.restore();
395: }
396: function drawProjectile() {
397:   if (!projectile) return;
398:   const t = Math.min(1, projectile.elapsed / projectile.duration);
399:   const x = projectile.from.x + (projectile.to.x - projectile.from.x) * t;
400:   const y = projectile.from.y + (projectile.to.y - projectile.from.y) * t - Math.sin(t * Math.PI) * Math.min(100, 44 + Math.abs(projectile.to.y - projectile.from.y) * .18);
401:   ctx.save();
402:   ctx.fillStyle = '#44552a30'; ctx.beginPath(); ctx.ellipse(x + 5, y + 14, 11 * (1 - t * .24), 4, 0, 0, Math.PI * 2); ctx.fill();
403:   ctx.font = `${25 * (1 - t * .1)}px "Apple Color Emoji","Segoe UI Emoji",sans-serif`;
404:   ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText(foodById(projectile.food).emoji, x, y);
405:   ctx.restore();
406: }
407: function drawParticles() {
408:   particles.forEach(particle => {
409:     const opacity = Math.max(0, particle.life / particle.maxLife);
410:     ctx.save(); ctx.globalAlpha = opacity; ctx.fillStyle = particle.color;
411:     if (particle.icon === '♥') {
412:       ctx.font = `${particle.size * 5}px sans-serif`; ctx.textAlign = 'center'; ctx.fillText('♥', particle.x, particle.y);
413:     } else {
414:       ctx.beginPath(); ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2); ctx.fill();
415:     }
416:     ctx.restore();
417:   });
418: }
419: function update(delta) {
420:   animals.forEach(animal => { animal.mood *= Math.pow(.001, delta); });
421:   if (projectile) {
422:     projectile.elapsed += delta;
423:     if (projectile.elapsed >= projectile.duration) { resolveThrow(); projectile = null; }
424:   }
425:   particles = particles.filter(particle => particle.life > 0);
426:   particles.forEach(particle => { particle.x += particle.vx * delta; particle.y += particle.vy * delta; particle.vy += 120 * delta; particle.life -= delta; });
427: }
428: function frame(time) {
429:   const delta = Math.min(.04, (time - lastTime) / 1000 || 0);
430:   lastTime = time;
431:   if (!reducedMotion) update(delta);
432:   drawBackground(time);
433:   requestAnimationFrame(frame);
434: }
